import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const Home = ({ user }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false); // Removi activeFaq/setActiveFaq

  // Navbar condicional
  const Navbar = () => (
    <header className="navbar">
      <div className="logo">🚗 CheckPort</div>
      <nav className={`nav-links ${isMenuOpen ? 'ativo' : ''}`}>
        {!user ? (
          <>
            <Link to="/">Início</Link>
            <Link to="/login">Login</Link>
            <Link to="/cadastrar">Cadastro</Link>
          </>
        ) : (
          <>
            <Link to="/listar">Lista</Link>
            <Link to="/buscar">Buscar</Link>
            <Link to="/dashboard">Dashboard</Link>
            <Link to="/perfil">Perfil</Link>
          </>
        )}
      </nav>
      <div className="hamburger" onClick={() => setIsMenuOpen(!isMenuOpen)}>
        ☰
      </div>
    </header>
  );

  // Seção Hero
  const HeroSection = () => (
    <section className="hero">
      <div className="hero-text">
        <h1>Controle inteligente de veículos</h1>
        <p>Simplifique a gestão de entrada e saída no seu porto ou empresa.</p>
        {!user && (
          <Link to="/cadastrar" className="btn-primary">
            Comece agora
          </Link>
        )}
      </div>
      <div className="hero-image">
        <img 
          src="https://placehold.co/600x400/8db986/white?text=CheckPort" 
          alt="Controle de veículos" 
        />
      </div>
    </section>
  );

  // Seção de Recursos
  const FeatureSection = () => (
    <section className="topicos">
      <div className="topico">
        <h3>📋 Listagem Completa</h3>
        <p>Acesso rápido a todos os motoristas cadastrados com filtros inteligentes.</p>
      </div>
      <div className="topico">
        <h3>🔍 Busca Avançada</h3>
        <p>Encontre qualquer veículo pela placa, modelo ou motorista em segundos.</p>
      </div>
      <div className="topico">
        <h3>📊 Dashboard</h3>
        <p>Relatórios em tempo real sobre movimentações e estatísticas.</p>
      </div>
    </section>
  );

  // Seção Sobre
  const AboutSection = () => (
    <section className="bloco">
      <div className="imagem">
        <img 
          src="https://placehold.co/450x300/acce91/white?text=Sistema+CheckPort" 
          alt="Sistema CheckPort" 
        />
      </div>
      <div className="texto">
        <h2>Como funciona</h2>
        <p>
          O CheckPort é a solução ideal para controle de acesso veicular em portos, 
          empresas e condomínios. Cadastre motoristas, gerencie entradas/saídas e 
          tenha relatórios detalhados em um só lugar.
        </p>
      </div>
    </section>
  );

  // Footer
  const Footer = () => (
    <footer>
      <div className="footer-links">
        <Link to="/politica">Política de Privacidade</Link>
        <Link to="/termos">Termos de Uso</Link>
      </div>
      <p>© {new Date().getFullYear()} CheckPort. Todos os direitos reservados.</p>
    </footer>
  );

  return (
    <div className="home-container">
      <Navbar />
      <HeroSection />
      <FeatureSection />
      <AboutSection />
      <Footer />
    </div>
  );
};

export default Home;
